export type experimentAnnotationsLogicType = MakeLogicType<
    experimentAnnotationsLogicValues,
    experimentAnnotationsLogicActions,
    ExperimentAnnotationsLogicProps,
    experimentAnnotationsLogicMeta
>

export const experimentAnnotationsLogic: LogicWrapper<experimentAnnotationsLogicType> =
    kea<experimentAnnotationsLogicType>([
        props({} as ExperimentAnnotationsLogicProps),
        key(({ experimentId }) => experimentId),
        path((key) => ['products', 'experiments', 'experimentAnnotationsLogic', key]),
        connect(() => ({ values: [teamLogic, ['currentProjectId']] })),
        actions({
            startAnnotation: (variantKey: string) => ({ variantKey }),
            editAnnotation: (annotation: ExperimentAnnotationApi) => ({ annotation }),
            closeEditor: true,
            setVariantKey: (variantKey: string) => ({ variantKey }),
            setContent: (content: string) => ({ content }),
        }),
        loaders(({ values, props }) => ({
            annotations: [
                [] as ExperimentAnnotationApi[],
                {
                    loadAnnotations: async () =>
                        experimentsAnnotationsList(String(values.currentProjectId), props.experimentId),
                },
            ],
            annotationMutation: [
                null as boolean | null,
                {
                    saveAnnotation: async () => {
                        const data = { variant_key: values.variantKey, content: values.content.trim() }
                        if (values.editingAnnotationId !== null) {
                            await experimentsAnnotationsPartialUpdate(
                                String(values.currentProjectId),
                                props.experimentId,
                                values.editingAnnotationId,
                                data
                            )
                        } else {
                            await experimentsAnnotationsCreate(
                                String(values.currentProjectId),
                                props.experimentId,
                                data
                            )
                        }
                        return true
                    },
                    deleteAnnotation: async (id: number) => {
                        await experimentsAnnotationsDestroy(String(values.currentProjectId), props.experimentId, id)
                        return true
                    },
                },
            ],
        })),
        reducers({
            editorOpen: [false, { startAnnotation: () => true, editAnnotation: () => true, closeEditor: () => false }],
            editingAnnotationId: [
                null as number | null,
                { startAnnotation: () => null, editAnnotation: (_, { annotation }) => annotation.id },
            ],
            variantKey: [
                '',
                {
                    startAnnotation: (_, { variantKey }) => variantKey,
                    editAnnotation: (_, { annotation }) => annotation.variant_key,
                    setVariantKey: (_, { variantKey }) => variantKey,
                },
            ],
            content: [
                '',
                {
                    startAnnotation: () => '',
                    editAnnotation: (_, { annotation }) => annotation.content,
                    setContent: (_, { content }) => content,
                },
            ],
            annotationsError: [false, { loadAnnotations: () => false, loadAnnotationsFailure: () => true }],
            mutationError: [
                false,
                {
                    startAnnotation: () => false,
                    editAnnotation: () => false,
                    saveAnnotation: () => false,
                    deleteAnnotation: () => false,
                    saveAnnotationFailure: () => true,
                    deleteAnnotationFailure: () => true,
                },
            ],
        }),
        listeners(({ actions }) => ({
            saveAnnotationSuccess: () => {
                actions.closeEditor()
                actions.loadAnnotations()
            },
            deleteAnnotationSuccess: () => actions.loadAnnotations(),
        })),
        afterMount(({ actions }) => actions.loadAnnotations()),
    ])
